    FOREIGN KEY (router_id) REFERENCES routers(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "security_group_rules" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "security_group_id" TEXT,
    "direction" TEXT NOT NULL CHECK (length("direction") <= 10),
    "ethertype" TEXT DEFAULT 'IPv4' CHECK (length("ethertype") <= 10),
    "protocol" TEXT CHECK (length("protocol") <= 10),
    "port_range_min" INTEGER,
    "port_range_max" INTEGER,
    "remote_ip_prefix" TEXT CHECK (length("remote_ip_prefix") <= 50),
    "remote_group_id" TEXT,
    "created_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    FOREIGN KEY (remote_group_id) REFERENCES security_groups(id) ON DELETE CASCADE,
    FOREIGN KEY (security_group_id) REFERENCES security_groups(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "server_migrations" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "server_uuid" TEXT NOT NULL,
    "source_node" TEXT CHECK (length("source_node") <= 255),
    "dest_node" TEXT CHECK (length("dest_node") <= 255),
    "old_flavor_id" TEXT,
    "new_flavor_id" TEXT,
    "status" TEXT DEFAULT 'queued' CHECK (length("status") <= 50),
    "migration_type" TEXT DEFAULT 'migration' CHECK (length("migration_type") <= 50),
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    FOREIGN KEY (server_uuid) REFERENCES instances(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "server_security_groups" (
    "server_id" TEXT NOT NULL,
    "security_group_id" TEXT NOT NULL,
    "created_at" TEXT NOT NULL DEFAULT (now()),
    PRIMARY KEY ("server_id", "security_group_id"),
    FOREIGN KEY (server_id) REFERENCES instances(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "server_tags" (
    "instance_id" TEXT NOT NULL,
    "tag" TEXT NOT NULL CHECK (length("tag") <= 60),
    "created_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("instance_id", "tag"),
    FOREIGN KEY (instance_id) REFERENCES instances(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "subnets" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "name" TEXT NOT NULL CHECK (length("name") <= 255),
    "network_id" TEXT,
    "project_id" TEXT,
    "cidr" TEXT NOT NULL CHECK (length("cidr") <= 50),
    "gateway_ip" TEXT CHECK (length("gateway_ip") <= 50),
    "ip_version" INTEGER DEFAULT 4,
    "enable_dhcp" INTEGER DEFAULT 1,
    "dns_nameservers" TEXT,
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    FOREIGN KEY (network_id) REFERENCES networks(id) ON DELETE CASCADE,
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "volumes" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "name" TEXT CHECK (length("name") <= 255),
    "project_id" TEXT,
    "user_id" TEXT,
    "size_gb" INTEGER NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'creating' CHECK (length("status") <= 50),
    "bootable" INTEGER DEFAULT 0,
    "attached_to_instance_id" TEXT,
    "rbd_pool" TEXT CHECK (length("rbd_pool") <= 255),
    "rbd_image" TEXT CHECK (length("rbd_image") <= 255),
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    "description" TEXT,
    "volume_type" TEXT CHECK (length("volume_type") <= 255),
    "source_image_id" TEXT,
    PRIMARY KEY ("id"),
    FOREIGN KEY (attached_to_instance_id) REFERENCES instances(id) ON DELETE SET NULL,
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) STRICT;

CREATE TABLE "floating_ips" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "project_id" TEXT,
    "floating_network_id" TEXT,
    "floating_ip_address" TEXT NOT NULL CHECK (length("floating_ip_address") <= 50),
    "fixed_ip_address" TEXT CHECK (length("fixed_ip_address") <= 50),
    "port_id" TEXT,
    "router_id" TEXT,
    "status" TEXT DEFAULT 'DOWN' CHECK (length("status") <= 50),
    "description" TEXT,
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    UNIQUE (floating_ip_address),
    FOREIGN KEY (floating_network_id) REFERENCES networks(id) ON DELETE CASCADE,
    FOREIGN KEY (port_id) REFERENCES ports(id) ON DELETE SET NULL,
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    FOREIGN KEY (router_id) REFERENCES routers(id) ON DELETE SET NULL
) STRICT;

CREATE TABLE "interface_attachments" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "instance_id" TEXT NOT NULL,
    "port_id" TEXT NOT NULL,
    "mac_address" TEXT NOT NULL CHECK (length("mac_address") <= 17),
    "attached_at" TEXT NOT NULL DEFAULT (now()),
    PRIMARY KEY ("id"),
    UNIQUE (instance_id, port_id),
    FOREIGN KEY (instance_id) REFERENCES instances(id) ON DELETE CASCADE,
    FOREIGN KEY (port_id) REFERENCES ports(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "port_security_groups" (
    "port_id" TEXT NOT NULL,
    "security_group_id" TEXT NOT NULL,
    PRIMARY KEY ("port_id", "security_group_id"),
    FOREIGN KEY (port_id) REFERENCES ports(id) ON DELETE CASCADE,
    FOREIGN KEY (security_group_id) REFERENCES security_groups(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "router_interfaces" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "router_id" TEXT,
    "port_id" TEXT,
    "subnet_id" TEXT,
    "created_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    UNIQUE (router_id, subnet_id),
    FOREIGN KEY (port_id) REFERENCES ports(id) ON DELETE CASCADE,
    FOREIGN KEY (router_id) REFERENCES routers(id) ON DELETE CASCADE,
    FOREIGN KEY (subnet_id) REFERENCES subnets(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "snapshots" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "name" TEXT CHECK (length("name") <= 255),
    "volume_id" TEXT,
    "project_id" TEXT,
    "size_gb" INTEGER NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'creating' CHECK (length("status") <= 50),
    "created_at" TEXT DEFAULT (now()),
    "description" TEXT,
    PRIMARY KEY ("id"),
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    FOREIGN KEY (volume_id) REFERENCES volumes(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "trunks" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "name" TEXT CHECK (length("name") <= 255),
    "description" TEXT,
    "project_id" TEXT NOT NULL,
    "port_id" TEXT NOT NULL,
    "admin_state_up" INTEGER DEFAULT 1,
    "status" TEXT DEFAULT 'ACTIVE' CHECK (length("status") <= 50),
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    UNIQUE (port_id),
    FOREIGN KEY (port_id) REFERENCES ports(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "volume_attachments" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "volume_id" TEXT NOT NULL,
    "instance_id" TEXT NOT NULL,
    "device" TEXT NOT NULL CHECK (length("device") <= 50),
    "attached_at" TEXT NOT NULL DEFAULT (now()),
    "delete_on_termination" INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    UNIQUE (instance_id, device),
    UNIQUE (volume_id),
    FOREIGN KEY (instance_id) REFERENCES instances(id) ON DELETE CASCADE,
    FOREIGN KEY (volume_id) REFERENCES volumes(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "volume_backups" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "project_id" TEXT NOT NULL,
    "volume_id" TEXT NOT NULL,
    "name" TEXT CHECK (length("name") <= 255),
    "description" TEXT,
    "status" TEXT DEFAULT 'creating' CHECK (length("status") <= 50),
    "size_gb" INTEGER NOT NULL,
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    FOREIGN KEY (volume_id) REFERENCES volumes(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "volume_metadata" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "volume_id" TEXT NOT NULL,
    "meta_key" TEXT NOT NULL CHECK (length("meta_key") <= 255),
    "meta_value" TEXT,
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    UNIQUE (volume_id, meta_key),
    FOREIGN KEY (volume_id) REFERENCES volumes(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "volume_transfers" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "volume_id" TEXT NOT NULL,
    "name" TEXT CHECK (length("name") <= 255),
    "source_project_id" TEXT NOT NULL,
    "destination_project_id" TEXT,
    "auth_key" TEXT NOT NULL CHECK (length("auth_key") <= 255),
    "accepted" INTEGER DEFAULT 0,
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    FOREIGN KEY (volume_id) REFERENCES volumes(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "vxlan_fdb_entries" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "network_id" TEXT,
    "mac_address" TEXT NOT NULL CHECK (length("mac_address") <= 17),
    "vtep_ip" TEXT NOT NULL CHECK (length("vtep_ip") <= 50),
    "port_id" TEXT,
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    UNIQUE (network_id, mac_address),
    FOREIGN KEY (network_id) REFERENCES networks(id) ON DELETE CASCADE,
    FOREIGN KEY (port_id) REFERENCES ports(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "port_forwardings" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "project_id" TEXT NOT NULL,
    "floatingip_id" TEXT NOT NULL,
    "internal_port_id" TEXT NOT NULL,
    "internal_ip_address" TEXT NOT NULL CHECK (length("internal_ip_address") <= 50),
    "external_port" INTEGER NOT NULL,
    "internal_port" INTEGER NOT NULL,
    "protocol" TEXT NOT NULL CHECK (length("protocol") <= 10),
    "status" TEXT DEFAULT 'ACTIVE' CHECK (length("status") <= 50),
    "description" TEXT,
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    UNIQUE (floatingip_id, external_port, protocol),
    FOREIGN KEY (floatingip_id) REFERENCES floating_ips(id) ON DELETE CASCADE,
    FOREIGN KEY (internal_port_id) REFERENCES ports(id) ON DELETE CASCADE,
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    CHECK (external_port >= 1 AND external_port <= 65535),
    CHECK (internal_port >= 1 AND internal_port <= 65535),
    CHECK (protocol IN ('tcp', 'udp'))
) STRICT;

CREATE TABLE "snapshot_metadata" (
    "id" TEXT NOT NULL DEFAULT (gen_random_uuid()),
    "snapshot_id" TEXT NOT NULL,
    "meta_key" TEXT NOT NULL CHECK (length("meta_key") <= 255),
    "meta_value" TEXT,
    "created_at" TEXT DEFAULT (now()),
    "updated_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("id"),
    UNIQUE (snapshot_id, meta_key),
    FOREIGN KEY (snapshot_id) REFERENCES snapshots(id) ON DELETE CASCADE
) STRICT;

CREATE TABLE "trunk_subports" (
    "trunk_id" TEXT NOT NULL,
    "port_id" TEXT NOT NULL,
    "segmentation_type" TEXT NOT NULL CHECK (length("segmentation_type") <= 50),
    "segmentation_id" INTEGER NOT NULL,
    "created_at" TEXT DEFAULT (now()),
    PRIMARY KEY ("trunk_id", "port_id"),
    FOREIGN KEY (port_id) REFERENCES ports(id) ON DELETE CASCADE,
    FOREIGN KEY (trunk_id) REFERENCES trunks(id) ON DELETE CASCADE
) STRICT;

